const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const polymod = (v) => { const G=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3]; let c=1;
  for (const d of v){ const b=c>>25; c=((c&0x1ffffff)<<5)^d; for(let i=0;i<5;i++) if((b>>i)&1) c^=G[i]; } return c; };
const hrpExpand = (h)=>[...[...h].map(c=>c.charCodeAt(0)>>5),0,...[...h].map(c=>c.charCodeAt(0)&31)];
const createChecksum=(h,d)=>{const v=[...hrpExpand(h),...d,0,0,0,0,0,0];const p=polymod(v)^1;
  return [0,1,2,3,4,5].map(i=>(p>>(5*(5-i)))&31);};
const encode=(h,d)=>h+'1'+[...d,...createChecksum(h,d)].map(i=>CHARSET[i]).join('');
function convertbits(data,from,to,pad=true){let acc=0,bits=0;const ret=[];const maxv=(1<<to)-1,ma=(1<<(from+to-1))-1;
  for(const v of data){if(v<0||(v>>from))return null;acc=((acc<<from)|v)&ma;bits+=from;
    while(bits>=to){bits-=to;ret.push((acc>>bits)&maxv);}}
  if(pad){if(bits)ret.push((acc<<(to-bits))&maxv);}else if(bits>=from||((acc<<(from-to))&maxv))return null;
  return ret;}
