/**
 * Bech32 character set (BIP173) and the lookup helpers built on top of it.
 *
 * Values are handled as ordinary JavaScript numbers inside plain arrays, so the
 * whole library stays on generic language primitives.
 */

/** The 32 data characters, in value order: index === 5-bit value. */
export const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";

/** The separator between the human-readable part and the data part. */
export const SEPARATOR = "1";

/**
 * Lowest / highest human-readable-part length accepted by BIP173.
 * Probing the reference implementation shows the HRP is the only
 * length-constrained piece: a 1..83 character HRP is accepted regardless of how
 * long the resulting string becomes.
 */
export const HRP_MIN_LENGTH = 1;
export const HRP_MAX_LENGTH = 83;

/** Number of trailing data symbols that form the checksum. */
export const CHECKSUM_LENGTH = 6;

/** Printable-ASCII window a bech32 string must live inside. */
export const MIN_CODE_POINT = 33;
export const MAX_CODE_POINT = 126;

const VALUE_BY_CHAR = new Map();
for (let value = 0; value < CHARSET.length; value += 1) {
  VALUE_BY_CHAR.set(CHARSET[value], value);
}

/**
 * Translate a data character to its 5-bit value.
 *
 * @param {string} char single character
 * @returns {number} the value, or -1 when the character is not in CHARSET
 */
export function charToValue(char) {
  const value = VALUE_BY_CHAR.get(char);
  return value === undefined ? -1 : value;
}

/**
 * @param {string} char single character
 * @returns {boolean} whether the character belongs to CHARSET
 */
export function isDataChar(char) {
  return VALUE_BY_CHAR.has(char);
}

/**
 * Map every character of a data part to its 5-bit value.
 *
 * @param {string} text the portion after the separator
 * @returns {number[]|null} values, or null if any character is out of CHARSET
 */
export function dataToValues(text) {
  const values = [];
  for (const char of text) {
    const value = charToValue(char);
    if (value < 0) {
      return null;
    }
    values.push(value);
  }
  return values;
}

/**
 * Reject strings holding characters outside the printable-ASCII window.
 *
 * @param {string} text
 * @returns {boolean}
 */
export function isPrintableAscii(text) {
  for (const char of text) {
    const code = char.codePointAt(0);
    if (code < MIN_CODE_POINT || code > MAX_CODE_POINT) {
      return false;
    }
  }
  return true;
}

/**
 * A bech32 string may be all lower case or all upper case, never a mixture.
 *
 * @param {string} text
 * @returns {boolean}
 */
export function hasConsistentCase(text) {
  return text.toLowerCase() === text || text.toUpperCase() === text;
}

