/**
 * The BCH checksum machinery behind bech32 (BIP173).
 *
 * Every intermediate value stays below 2^30, so the 32-bit semantics of the
 * JavaScript bitwise operators are exact here — no wider integer type needed.
 */

import { CHECKSUM_LENGTH } from "./charset.mjs";

/** Generator coefficients of the BCH code. */
const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

/**
 * Run the generator polynomial over a sequence of 5-bit values.
 *
 * @param {number[]} values
 * @returns {number} the 30-bit residue
 */
export function polymod(values) {
  let checksum = 1;
  for (const value of values) {
    const top = checksum >> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < GENERATOR.length; i += 1) {
      if ((top >> i) & 1) {
        checksum ^= GENERATOR[i];
      }
    }
  }
  return checksum;
}

/**
 * Expand the human-readable part into the 5-bit values the checksum covers:
 * the high bits of every character, a zero separator, then the low bits.
 *
 * @param {string} hrp
 * @returns {number[]}
 */
export function hrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const char of hrp) {
    const code = char.codePointAt(0);
    high.push(code >> 5);
    low.push(code & 31);
  }
  return [...high, 0, ...low];
}

/**
 * Check the trailing six data symbols against the rest of the string.
 *
 * @param {string} hrp human-readable part, already lower cased
 * @param {number[]} data data part including its checksum
 * @returns {boolean}
 */
export function verifyChecksum(hrp, data) {
  return polymod([...hrpExpand(hrp), ...data]) === 1;
}

/**
 * Split the checksum symbols off a verified data part.
 *
 * @param {number[]} data data part including its checksum
 * @returns {number[]} the payload symbols
 */
export function stripChecksum(data) {
  return data.slice(0, data.length - CHECKSUM_LENGTH);
}

