const MIN_PROGRAM_LENGTH = 2;
const MAX_PROGRAM_LENGTH = 40;
/** Version 0 programs are pinned to these two widths. */
const V0_PROGRAM_LENGTHS = [20, 32];

/**
 * Validate a bech32 string and split it into its two halves.
 *
