/**
 * Rendering of values the way Python's `print` renders them, so stdout matches
 * the original program byte for byte.
 */

/**
 * Format a value using Python's `repr` rules for the types this program prints:
 * `None`, integers and lists of integers.
 *
 * @param {*} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) {
    return "None";
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(", ")}]`;
  }
  return String(value);
}

/**
 * Write one value followed by a newline, as `print` does.
 *
 * @param {*} value
 */
export function pyPrint(value) {
  process.stdout.write(`${pyRepr(value)}\n`);
}

