/**
 * A faithful subset of Python's `argparse`, covering exactly the surface the
 * ported program relies on: required `--name value` string options plus the
 * automatic `-h/--help` action.
 *
 * Reproduced behaviours (all verified against the reference build):
 *   - `--a value` and `--a=value` forms; unique prefixes such as `--he` resolve.
 *   - A value starting with `-` is rejected as a missing argument, unless it is
 *     a lone `-`, contains a space, or looks like a negative number.
 *   - `-h` / `--help` prints the help text and exits 0, even mid-command line.
 *   - Missing required options are reported before unrecognized ones; both exit
 *     with status 2 after printing the usage line to stderr.
 *   - A repeated option keeps the last value given.
 */

/** Values matching this are read as negative numbers, not as option names. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** argparse's HelpFormatter defaults. */
const INDENT = 2;
const MAX_HELP_POSITION = 24;

const EXIT_ERROR = 2;

export class ArgumentParser {
  /**
   * @param {{prog: string}} options program name used in usage and errors
   */
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(["-h", "--help"], {
      kind: "help",
      help: "show this help message and exit",
    });
  }

  /**
   * Register an option.
   *
   * @param {string|string[]} optionStrings e.g. `"--a"` or `["-h", "--help"]`
   * @param {{kind?: string, required?: boolean, help?: string}} [options]
   * @returns {object} the created action
   */
  addArgument(optionStrings, { kind = "store", required = false, help = null } = {}) {
    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const longest = strings.find((s) => s.startsWith("--")) ?? strings[0];
    const dest = longest.replace(/^-+/, "").replace(/-/g, "_");
    const takesValue = kind !== "help";
    const action = {
      optionStrings: strings,
      dest,
      kind,
      required,
      help,
      takesValue,
      metavar: takesValue ? dest.toUpperCase() : null,
    };
    this.actions.push(action);
    for (const optionString of strings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  /** @returns {string} the name argparse uses for an action in messages */
  actionName(action) {
    return action.optionStrings.join("/");
  }

  /** @returns {string} the single-line usage string, without trailing newline */
  formatUsage() {
    const parts = this.actions.map((action) => {
      const head = action.optionStrings[0];
      const body = action.takesValue ? `${head} ${action.metavar}` : head;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${[this.prog, ...parts].join(" ")}`;
  }

  /** @returns {string} what argparse writes for `-h`, newline terminated */
  formatHelp() {
    const invocations = this.actions.map((action) =>
      action.optionStrings
        .map((s) => (action.takesValue ? `${s} ${action.metavar}` : s))
        .join(", ")
    );
    const actionMaxLength = Math.max(
      ...invocations.map((invocation) => invocation.length + INDENT)
    );
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - INDENT - 2;
    const pad = " ".repeat(INDENT);

    const lines = [this.formatUsage(), "", "options:"];
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (!action.help) {
        lines.push(`${pad}${invocation}`);
      } else if (invocation.length <= actionWidth) {
        lines.push(`${pad}${invocation.padEnd(actionWidth)}  ${action.help}`);
      } else {
        lines.push(`${pad}${invocation}`);
        lines.push(`${" ".repeat(helpPosition)}${action.help}`);
      }
    });
    return `${lines.join("\n")}\n`;
  }

  /**
   * Print the usage line plus an error, then exit with status 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    process.stderr.write(`${this.formatUsage()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(EXIT_ERROR);
  }

  /**
   * Collect the options whose name starts with the given `--` prefix.
   *
   * @param {string} argString
   * @returns {Array<[object, string, string|null]>}
   */
  optionTuples(argString) {
    const tuples = [];
    if (argString.startsWith("--")) {
      let prefix = argString;
      let explicitArg = null;
      const equals = argString.indexOf("=");
      if (equals >= 0) {
        prefix = argString.slice(0, equals);
        explicitArg = argString.slice(equals + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) {
          tuples.push([action, optionString, explicitArg]);
        }
      }
      return tuples;
    }
    // Single dash: either an exact short option carrying its value, or a prefix.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicit = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        tuples.push([action, optionString, shortExplicit]);
      } else if (optionString.startsWith(argString)) {
        tuples.push([action, optionString, null]);
      }
    }
    return tuples;
  }

  /**
   * Decide whether a command line token is an option.
   *
   * @param {string} argString
   * @returns {[object|null, string, string|null]|null} null means "not an
   *   option"; a leading null action means "an option we do not know"
   */
  parseOptional(argString) {
    if (!argString) {
      return null;
    }
    if (argString[0] !== "-") {
      return null;
    }
    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) {
      return null;
    }
    const equals = argString.indexOf("=");
    if (equals >= 0) {
      const head = argString.slice(0, equals);
      if (this.optionStringActions.has(head)) {
        return [this.optionStringActions.get(head), head, argString.slice(equals + 1)];
      }
    }
    const tuples = this.optionTuples(argString);
    if (tuples.length > 1) {
      const names = tuples.map(([, optionString]) => optionString).join(", ");
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (tuples.length === 1) {
      return tuples[0];
    }
    if (NEGATIVE_NUMBER.test(argString)) {
      return null;
    }
    if (argString.includes(" ")) {
      return null;
    }
    return [null, argString, null];
  }

  /**
   * Parse a command line.
   *
   * @param {string[]} argv tokens after the program name
   * @returns {Object<string, string|null>} the resulting namespace
   */
  parseArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (action.takesValue) {
        namespace[action.dest] = null;
      }
    }

    const extras = [];
    const seen = new Set();
    let sawDoubleDash = false;
    let index = 0;

    while (index < argv.length) {
      const argString = argv[index];

      // `--` switches to positional-only mode. With no positionals declared it
      // is never consumed as a separator, so it lands in the extras itself.
      if (sawDoubleDash || argString === "--") {
        sawDoubleDash = true;
        extras.push(argString);
        index += 1;
        continue;
      }

      const optional = this.parseOptional(argString);
      if (optional === null || optional[0] === null) {
        extras.push(argString);
        index += 1;
        continue;
      }

      const [action, optionString, explicitArg] = optional;
      if (action.kind === "help") {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      if (explicitArg !== null) {
        namespace[action.dest] = explicitArg;
        seen.add(action);
        index += 1;
        continue;
      }

      const next = argv[index + 1];
      if (next === undefined || this.parseOptional(next) !== null) {
        this.error(`argument ${this.actionName(action)}: expected one argument`);
      }
      namespace[action.dest] = next;
      seen.add(action);
      index += 2;
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length > 0) {
      const names = missing.map((action) => this.actionName(action)).join(", ");
      this.error(`the following arguments are required: ${names}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(" ")}`);
    }

    return namespace;
  }
}

