/**
 * Port of dataset/bech32/test12.py.
 *
 * Reads a human-readable part (--a) and a segwit address (--b), decodes the
 * address, and — when it decodes — prints the witness version followed by the
 * result of running the witness program back through a 5-to-8 bit conversion.
 * That second conversion only succeeds when every program byte happens to fit
 * in 5 bits, so `None` is the usual second line.
 */

import { ArgumentParser } from "./lib/argparse.mjs";
import { convertbits, decode } from "./lib/bech32.mjs";
import { pyPrint } from "./lib/pyformat.mjs";

/**
 * Program name for usage and error messages. argparse derives this from
 * argv[0]; it is pinned here so the usage line and the exit-status-2 errors
 * match the reference build byte for byte.
 */
const PROG = "test12_executable";

/**
 * @param {string[]} [argv] command line tokens after the script name
 */
export function main(argv = process.argv.slice(2)) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument("--a", { required: true }); // HRP
  parser.addArgument("--b", { required: true }); // Segwit address
  const args = parser.parseArgs(argv);

  const decoded = decode(args.a, args.b); // Decode segwit address
  if (decoded[0] !== null && decoded[1] !== null) {
    const [witver, witprog] = decoded;
    const converted = convertbits(witprog, 5, 8); // Convert 5-bit to 8-bit
    pyPrint(witver);
    pyPrint(converted);
  }
}

main();

