toolUseResult.originalFile:
/**
 * General power-of-two base conversion, as exposed by `bech32.convertbits`.
 */

/**
 * Regroup a sequence of `frombits`-wide values into `tobits`-wide values.
 *
 * With `pad` enabled a trailing partial group is zero-extended into one more
 * output value. With `pad` disabled the leftover bits must be fewer than
 * `frombits` and all zero, otherwise the input is rejected.
 *
 * Any input value that does not fit in `frombits` bits (or is negative) makes
 * the whole conversion fail.
 *
 * @param {number[]} data input values
 * @param {number} frombits width of each input value
 * @param {number} tobits width of each output value
 * @param {boolean} [pad=true] whether to zero-pad the final group
 * @returns {number[]|null} the regrouped values, or null on failure
 */
export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const result = [];
  const maxValue = (1 << tobits) - 1;
  const maxAcc = (1 << (frombits + tobits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || value >> frombits) {
      return null;
    }
    acc = ((acc << frombits) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      result.push((acc >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits) {
      result.push((acc << (tobits - bits)) & maxValue);
    }
  } else if (bits >= frombits || ((acc << (frombits - tobits)) & maxValue)) {
    return null;
  }

  return result;
}

