// Differential runner: feeds each JSONL argv array to the reference executable
// and to the node port, then compares stdout, stderr and exit status.
import { readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";

const REF = "/workspace/dataset/test12_executable";
const cases = readFileSync(process.argv[2], "utf8")
  .split("\n")
  .filter((line) => line.length > 0)
  .map((line) => JSON.parse(line));

let pass = 0;
const failures = [];
for (const argv of cases) {
  const r = spawnSync(REF, argv, { encoding: "utf8" });
  const j = spawnSync("node", ["/output/test12.mjs", ...argv], { encoding: "utf8" });
  if (r.stdout === j.stdout && r.stderr === j.stderr && r.status === j.status) {
    pass += 1;
  } else if (failures.length < 12) {
    failures.push({ argv, ref: [r.status, r.stdout, r.stderr], js: [j.status, j.stdout, j.stderr] });
  } else {
    failures.push(null);
  }
}
for (const f of failures) {
  if (f) console.log("MISMATCH", JSON.stringify(f, null, 1));
}
console.log(`PASS=${pass} FAIL=${cases.length - pass} TOTAL=${cases.length}`);

