// Random argv shapes to stress the argparse port (option forms, unknown flags,
// dash-leading values, abbreviations, `--`, repeats, help placement).
let s = 987654321;
const rnd = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
const ri = (n) => Math.floor(rnd() * n);

const TOKENS = [
  "--a", "--b", "-h", "--help", "--he", "--hel", "--h", "-x", "--c", "--ab", "--",
  "-", "-1", "-1.5", "-1x", "-bc", "- x", "-x y", "bc", "tb", "bc1sqypqyquhk7",
  "extra", "", "--a=bc", "--b=bc1sqypqyquhk7", "--a=", "--b=", "--a=-bc",
  "--=x", "--a=bc=tb", "=", "--A", "-hh", "-h=x", "--help=x", "--b=bc1zzz",
];

const out = [];
for (let i = 0; i < 1400; i++) {
  const n = ri(6);
  const argv = [];
  for (let j = 0; j < n; j++) argv.push(TOKENS[ri(TOKENS.length)]);
  out.push(JSON.stringify(argv));
}
// Plus every single token alone, and every ordered pair of a focused subset.
for (const t of TOKENS) out.push(JSON.stringify([t]));
const FOCUS = ["--a", "--b", "-h", "--", "-x", "bc", "-1", "--a=bc", ""];
for (const p of FOCUS) for (const q of FOCUS) out.push(JSON.stringify([p, q]));
process.stdout.write(out.join("\n") + "\n");

