import { readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";

const REF = "/workspace/dataset/test12_executable";
const cases = readFileSync(process.argv[2], "utf8")
  .split("\n").filter((l) => l.length > 0).map((l) => JSON.parse(l));

const kinds = new Map();
let pass = 0;
for (const argv of cases) {
  const r = spawnSync(REF, argv, { encoding: "utf8" });
  const j = spawnSync("node", ["/output/test12.mjs", ...argv], { encoding: "utf8" });
  if (r.stdout === j.stdout && r.stderr === j.stderr && r.status === j.status) { pass += 1; continue; }
  const norm = (s) => s.split("\n").filter((x) => x.includes("error:")).join("|") || `<rc${r.status}:${s.slice(0, 20)}>`;
  const key = `REF[${norm(r.stderr || r.stdout)}] JS[${norm(j.stderr || j.stdout)}]`;
  if (!kinds.has(key)) kinds.set(key, { count: 0, sample: argv });
  const e = kinds.get(key); e.count += 1;
}
for (const [k, v] of [...kinds].sort((a, b) => b[1].count - a[1].count)) {
  console.log(`${String(v.count).padStart(4)}  ${k}\n      sample: ${JSON.stringify(v.sample)}`);
}
console.log(`PASS=${pass} FAIL=${cases.length - pass} TOTAL=${cases.length}`);

